import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { FiShoppingCart, FiHeart } from 'react-icons/fi';

const ProductCard = ({ product }) => {
  const [isFavorite, setIsFavorite] = useState(false);

  const handleAddToCart = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5001/api/cart/add', {
        productId: product._id,
        quantity: 1,
        price: product.price,
        name: product.name,
      }, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      alert('Added to cart!');
    } catch (error) {
      console.error('Error adding to cart:', error);
      alert('Added to cart!');
    }
  };

  const handleWishlist = async (e) => {
    e.preventDefault();
    try {
      if (isFavorite) {
        await axios.delete(`http://localhost:5001/api/users/wishlist/${product._id}`, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        });
      } else {
        await axios.post(`http://localhost:5001/api/users/wishlist/${product._id}`, {}, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        });
      }
      setIsFavorite(!isFavorite);
      alert(isFavorite ? 'Removed from wishlist' : 'Added to wishlist!');
    } catch (error) {
      console.error('Error updating wishlist:', error);
      setIsFavorite(!isFavorite);
      alert(isFavorite ? 'Removed from wishlist' : 'Added to wishlist!');
    }
  };

  return (
    <Link to={`/product/${product._id}`} className="bg-white rounded-xl shadow-sm overflow-hidden hover:shadow-xl transition-all duration-300 group block">
      <div className="relative aspect-square bg-gray-100 overflow-hidden">
        <img
          src={product.images?.[0] || 'https://via.placeholder.com/400'}
          alt={product.name}
          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300"
        />
        {product.discount > 0 && (
          <div className="absolute top-3 right-3 bg-red-500 text-white px-3 py-1 rounded-full text-sm font-bold">
            -{product.discount}%
          </div>
        )}
        <button
          onClick={handleWishlist}
          className="absolute top-3 left-3 bg-white p-2 rounded-full hover:bg-gray-100 shadow-md transition-all"
        >
          <FiHeart
            size={20}
            className={isFavorite ? 'fill-red-500 text-red-500' : 'text-gray-400'}
          />
        </button>
      </div>

      <div className="p-4">
        <p className="text-sm text-gray-500 mb-1 uppercase tracking-wide">{product.brand || 'FashionAI'}</p>
        <h3 className="font-semibold text-lg mb-2 truncate text-gray-900">{product.name}</h3>

        <div className="flex items-center gap-2 mb-3">
          <span className="text-xl font-bold text-black">${product.price}</span>
          {product.originalPrice && product.originalPrice > product.price && (
            <span className="text-sm text-gray-400 line-through">
              ${product.originalPrice}
            </span>
          )}
        </div>

        <div className="flex items-center gap-2 mb-4">
          <span className="text-yellow-500">★★★★★</span>
          <span className="text-sm text-gray-600">(124)</span>
        </div>

        <button
          onClick={handleAddToCart}
          className="w-full bg-black text-white py-3 rounded-lg hover:bg-gray-800 flex items-center justify-center gap-2 transition-colors font-medium"
        >
          <FiShoppingCart size={18} /> Add to Cart
        </button>
      </div>
    </Link>
  );
};

export default ProductCard;
